<?php
declare(strict_types=1);
final class AnalysisService {private function ema(array $v,int $p):array{$a=2/($p+1);$o=[];$last=(float)$v[0];foreach($v as $i=>$x){$last=$i===0?(float)$x:(float)$x*$a+$last*(1-$a);$o[]=$last;}return $o;}public function analyze(array $c):array{if(count($c)<30)return ['decision'=>'WAIT','reason'=>'Insufficient verified candles.','trend'=>'Unknown','rsi'=>null,'volatility'=>null,'confirmation'=>false,'quality'=>'insufficient'];$cl=array_column($c,'close');$hi=array_column($c,'high');$lo=array_column($c,'low');$e20=$this->ema($cl,20);$e50=$this->ema($cl,50);$d=[];for($i=1;$i<count($cl);$i++)$d[]=$cl[$i]-$cl[$i-1];$d=array_slice($d,-14);$g=array_sum(array_map(fn($x)=>max(0,$x),$d))/max(1,count($d));$l=array_sum(array_map(fn($x)=>max(0,-$x),$d))/max(1,count($d));$rsi=$l==0?100:100-(100/(1+$g/$l));$tr=[];for($i=max(1,count($cl)-14);$i<count($cl);$i++)$tr[]=max($hi[$i]-$lo[$i],abs($hi[$i]-$cl[$i-1]),abs($lo[$i]-$cl[$i-1]));$atr=array_sum($tr)/max(1,count($tr));$last=end($cl);$a=end($e20);$b=end($e50);$trend=$last>$a&&$a>$b?'Bullish structure':($last<$a&&$a<$b?'Bearish structure':'Mixed / range');$reason='No high-quality entry condition is confirmed. Wait for structure, trigger and risk levels to align.';if($rsi>=70)$reason='Momentum is elevated; chasing can increase reversal risk. Wait for a fresh setup.';elseif($rsi<=30)$reason='Momentum is weak/oversold; avoid chasing and wait for confirmation.';elseif($trend==='Bullish structure'&&$rsi>=50)$reason='Bullish structure is present, but this is not an entry signal. Require a defined trigger, invalidation and acceptable risk.';elseif($trend==='Bearish structure'&&$rsi<=50)$reason='Bearish structure is present, but this is not an entry signal. Require a defined trigger, invalidation and acceptable risk.';return ['decision'=>'WAIT','reason'=>$reason,'trend'=>$trend,'rsi'=>round($rsi,2),'volatility'=>round($atr,8),'ema20'=>round($a,8),'ema50'=>round($b,8),'last'=>$last,'confirmation'=>false,'quality'=>'calculated','timestamp'=>time()];}}
